    cmds = _parse(line, env, strict, False)
    return cmds[0] if cmds else []


def split_commands(line, env=None, strict=False):
    return _parse(line, env, strict, True)


def quote(word):
    if word == "":
        return "''"
    if _SAFE.fullmatch(word):
        return word
    return "'" + word.replace("'", "'\"'\"'") + "'"


def join(words):
    return " ".join(quote(w) for w in words)

