                word = []
            word.append(line[i + 1])
            i += 2
        elif c != "$":
            if word is None:
                word = []
            text, i = _expand(line, i, env, strict)
            word.append(text)
        elif c == "~" and word is None and (i + 1 == n or line[i + 1] in _SPACE + "/" + (";" if semicolons else "")):
            word = [env["HOME"] if env and "HOME" in env else "~"]
            i += 1
        else:
            if word is None:
                word = []
            word.append(c)
            i += 1
