    return _parse(line, env, strict, True)


def quote(word):
    if word == "":
        return "''"
    if _SAFE.fullmatch(word):
        return word
    return "'" + word.replace("'", "'\"'\"'") + "'"


def join(words):
    return " ".join(quote(w) for w in words)

