                i += 1
        elif c == ";" and semicolons:
            if word is not None:
                cmds[-1].append("".join(word))
                word = None
            cmds.append([])
            i += 1
        elif c == "'":
            j = line.find("'", i + 1)
            if j < 0:
                raise ValueError("unterminated single quote")
            if word is None:
                word = []
            word.append(line[i + 1:j])
            i = j + 1
