        self.assertEqual(split(r'"a\"b"'), ['a"b'])
        self.assertEqual(split(r'"a\\b"'), ["a\\b"])
        self.assertEqual(split(r'"\$HOME"', {"HOME": "/h"}), ["$HOME"])
        self.assertEqual(split(r'"a\nb\tc"'), ["a\nb\tc"])

