        self.assertEqual(split("ab\\\ncd"), ["abcd"])
        self.assertEqual(split("ab \\\ncd"), ["ab", "cd"])
        self.assertEqual(split("\\\n"), [])
        self.assertEqual(split("a\\\n\\\nb"), ["ab"])

